CREATE TABLE departments (id INTEGER PRIMARY KEY AUTOINCREMENT, name TEXT NOT NULL UNIQUE);
CREATE TABLE stages (slug TEXT PRIMARY KEY, position INTEGER NOT NULL, name TEXT NOT NULL);
CREATE TABLE nodes (slug TEXT PRIMARY KEY, stage_slug TEXT NOT NULL REFERENCES stages(slug), position INTEGER NOT NULL, name TEXT NOT NULL, duration_rule TEXT NOT NULL DEFAULT '', duration_days INTEGER NOT NULL DEFAULT 0, remind_days_before INTEGER NOT NULL DEFAULT 0);
CREATE INDEX nodes_stage_position ON nodes(stage_slug, position);
CREATE TABLE materials (id INTEGER PRIMARY KEY AUTOINCREMENT, slug TEXT NOT NULL UNIQUE, stage_slug TEXT NOT NULL REFERENCES stages(slug), node_slug TEXT REFERENCES nodes(slug), name TEXT NOT NULL, category TEXT NOT NULL, fill_method TEXT NOT NULL, writing_points TEXT NOT NULL DEFAULT '', required INTEGER NOT NULL DEFAULT 1);
CREATE INDEX materials_stage ON materials(stage_slug);
CREATE TABLE users (id INTEGER PRIMARY KEY AUTOINCREMENT, username TEXT NOT NULL UNIQUE COLLATE NOCASE, password_salt TEXT NOT NULL, password_verifier TEXT NOT NULL, role TEXT NOT NULL CHECK(role IN ('admin','counselor','student')), department_id INTEGER REFERENCES departments(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE profiles (user_id INTEGER PRIMARY KEY REFERENCES users(id) ON DELETE CASCADE, name TEXT NOT NULL, student_no TEXT NOT NULL UNIQUE, major TEXT NOT NULL DEFAULT '', grade TEXT NOT NULL DEFAULT '', phone TEXT NOT NULL DEFAULT '', applied_at TEXT, current_stage_slug TEXT NOT NULL DEFAULT 'application', current_node_slug TEXT NOT NULL DEFAULT 'apply', node_entered_at TEXT, is_graduate INTEGER NOT NULL DEFAULT 0);
CREATE TABLE invites (id INTEGER PRIMARY KEY AUTOINCREMENT, code_hash TEXT NOT NULL UNIQUE, role TEXT NOT NULL CHECK(role IN ('student','counselor')), department_id INTEGER REFERENCES departments(id), expires_at TEXT NOT NULL, used_by INTEGER REFERENCES users(id), created_by INTEGER REFERENCES users(id), created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE sessions (token_hash TEXT PRIMARY KEY, user_id INTEGER NOT NULL REFERENCES users(id) ON DELETE CASCADE, expires_at TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE INDEX sessions_user ON sessions(user_id);
CREATE TABLE material_records (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL REFERENCES users(id), material_id INTEGER NOT NULL REFERENCES materials(id), status TEXT NOT NULL DEFAULT '未交' CHECK(status IN ('未交','已交','已通过')), r2_key TEXT, filename TEXT, submitted_at TEXT, UNIQUE(student_id, material_id));
CREATE TABLE notifications (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL REFERENCES users(id), kind TEXT NOT NULL, title TEXT NOT NULL, content TEXT NOT NULL, node_slug TEXT REFERENCES nodes(slug), is_read INTEGER NOT NULL DEFAULT 0, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE UNIQUE INDEX notification_deadline_once ON notifications(student_id,node_slug,kind) WHERE kind='deadline';
CREATE TABLE checks (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL REFERENCES users(id), material_id INTEGER NOT NULL REFERENCES materials(id), r2_key TEXT NOT NULL, filename TEXT NOT NULL, checked_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE check_results (id INTEGER PRIMARY KEY AUTOINCREMENT, check_id INTEGER NOT NULL REFERENCES checks(id) ON DELETE CASCADE, kind TEXT NOT NULL, code TEXT NOT NULL, message TEXT NOT NULL, severity TEXT NOT NULL, suggestion TEXT NOT NULL);
CREATE TABLE chat_sessions (id INTEGER PRIMARY KEY AUTOINCREMENT, student_id INTEGER NOT NULL REFERENCES users(id), title TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE chat_messages (id INTEGER PRIMARY KEY AUTOINCREMENT, session_id INTEGER NOT NULL REFERENCES chat_sessions(id) ON DELETE CASCADE, role TEXT NOT NULL, content TEXT NOT NULL, created_at TEXT NOT NULL DEFAULT CURRENT_TIMESTAMP);
CREATE TABLE login_attempts (key TEXT PRIMARY KEY, count INTEGER NOT NULL, reset_at TEXT NOT NULL);
